cards.extra:
echo '== imports'; I=$(go list -e -overlay $P/overlay.json -f '{{join .Imports " "}}' ./api) || exit 1; for i in $I; do case $i in crypto/subtle|encoding/json|errors|io|mime|net/http|strconv|strings|morphstudio/control|morphstudio/queue) ;; *) echo "imports: package api imports $i (allowed: crypto/subtle, encoding/json, errors, io, mime, net/http, strconv, strings, morphstudio/control, morphstudio/queue)"; exit 1;; esac; done
echo '== clock'; C=$(gofmt -l -r 'time.Now -> time.Time' api/handlers.go 2>&1)$(gofmt -l -r 'time.Since -> time.Time' api/handlers.go 2>&1); [ -z "$C" ] || { echo "clock: api/handlers.go reads time.Now or time.Since (the clock is the now argument)"; exit 1; }
echo '== net'; for x in http.DefaultClient http.Get http.Post http.PostForm http.Head http.ListenAndServe http.ListenAndServeTLS; do C=$(gofmt -l -r "$x -> http.NoBody" api/handlers.go 2>&1); [ -z "$C" ] || { echo "net: api/handlers.go uses $x (no HTTP client and never a listener in package api)"; exit 1; }; done

echo '== imports'; I=$(go list -e -overlay $P/overlay.json -f '{{join .Imports " "}}' ./api) || exit 1; for i in $I; do case $i in crypto/subtle|encoding/json|errors|io|mime|net/http|strconv|strings|morphstudio/control|morphstudio/queue) ;; *) echo "imports: package api imports $i (allowed: crypto/subtle, encoding/json, errors, io, mime, net/http, strconv, strings, morphstudio/control, morphstudio/queue)"; exit 1;; esac; done
echo '== clock'; C=$(gofmt -l -r 'time.Now -> time.Time' api/router.go 2>&1)$(gofmt -l -r 'time.Since -> time.Time' api/router.go 2>&1); [ -z "$C" ] || { echo "clock: api/router.go reads time.Now or time.Since (the clock is the now argument)"; exit 1; }
echo '== net'; for x in http.DefaultClient http.Get http.Post http.PostForm http.Head http.ListenAndServe http.ListenAndServeTLS; do C=$(gofmt -l -r "$x -> http.NoBody" api/router.go 2>&1); [ -z "$C" ] || { echo "net: api/router.go uses $x (no HTTP client and never a listener in package api)"; exit 1; }; done
